// REGENLANE-1 acceptance battery — the block-and-regenerate lane. Every
// flagged prose unit gets ONE chance to be regenerated by the model under a
// deterministic verifier; otherwise it stays flagged. Nothing here regex-edits
// prose. Fixtures use invented generic names (Mara, Dov, Ilse), never a real
// book's cast.
import fs from 'node:fs';
import {
  REGENLANE_VERSION,
  collectRegenTargets,
  verifyRegeneratedParagraph,
  regenerateFlaggedParagraphs,
} from '../src/lib/regenerateLane.js';

let failures = 0;
const check = (name, pass, detail) => { console.log((pass ? 'PASS ' : 'FAIL ') + name + (pass || !detail ? '' : `\n      ${detail}`)); if (!pass) failures += 1; };
const CAST = ['Mara', 'Dov', 'Ilse'];

// ── 1. version ──
check('1. version', REGENLANE_VERSION === 'regen-lane-v1');

// ── 2. collects a dropped-subject paragraph ──
{
  const text = 'Mara walked into the room and sat down at the table.\n\nWere a ragtag collection of misfits, but they kept moving toward the ridge anyway.\n\nIlse smiled at the window and said nothing at all.';
  const targets = collectRegenTargets(text, { cast: CAST });
  check('2. collects a dropped-subject paragraph', targets.some((t) => t.kind === 'dropped-subject'));
}

// ── 3. collects a duplicate self-introduction ──
{
  const text = 'Dov walked into the tavern and looked around at the crowded room full of strangers, and after a moment. “I am Mara,” she said, offering her hand to the stranger by the fire.\n\nDov nodded and gestured Ilse toward the empty table near the window, and once they sat. “I am Mara,” she said again, laughing under her breath at the echo of it.';
  const targets = collectRegenTargets(text, { cast: CAST });
  check('3. collects a duplicate self-introduction', targets.some((t) => t.kind === 'duplicate-introduction'), JSON.stringify(targets));
}

// ── 4. collects a departed-active sentence ──
{
  const text = 'Dov sat by the window and watched the rain fall in long gray sheets.\n\nMara walked into the kitchen and poured a cup of coffee before anyone else woke.\n\nIlse read quietly in the corner, undisturbed by the weather outside.';
  const targets = collectRegenTargets(text, { cast: CAST, departed: ['Mara'] });
  check('4. collects a departed-active sentence', targets.some((t) => t.kind === 'departed-active'), JSON.stringify(targets));
}

// ── 5. accepts a clean rewrite and replaces exactly once ──
{
  const text = 'Mara walked into the room and sat down at the table.\n\nWere a ragtag collection of misfits, but they kept moving toward the ridge anyway.\n\nIlse smiled at the window and said nothing at all.';
  const mockLLM = async () => 'The group was a ragtag collection of misfits, but they kept moving toward the ridge anyway.';
  const result = await regenerateFlaggedParagraphs(text, { cast: CAST, callLLM: mockLLM, project: { book_type: 'fiction' } });
  check('5. accepts a clean rewrite and replaces exactly once', result.regenerated === 1 && result.text.includes('The group was a ragtag collection') && !result.text.includes('Were a ragtag collection'), JSON.stringify(result));
}

// ── unit-level verifier checks (verifyRegeneratedParagraph) ──

// 6. rejects new proper noun
{
  const original = 'Were a ragtag collection of misfits, but they kept moving toward the ridge anyway.';
  const candidate = 'They were, as Baxter put it, a ragtag collection of misfits, but they kept moving toward the ridge anyway.';
  const verdict = verifyRegeneratedParagraph(original, candidate, { cast: CAST });
  check('6. rejects new proper noun', verdict.reason?.startsWith('new-proper-noun'), JSON.stringify(verdict));
}

// 7. rejects two paragraphs (paragraph-count)
{
  const original = 'Mara walked slowly across the room toward the door.';
  const candidate = 'Mara walked slowly across the room.\n\nThen she reached the door.';
  const verdict = verifyRegeneratedParagraph(original, candidate, { cast: CAST });
  check('7. rejects two paragraphs (paragraph-count)', verdict.reason === 'paragraph-count', JSON.stringify(verdict));
}

// 8. rejects still-flagged
{
  const original = 'Mara walked slowly across the room toward the door.';
  const candidate = 'Mara moved slowly across the room toward the door.';
  const verdict = verifyRegeneratedParagraph(original, candidate, { cast: CAST, rescan: () => [{ kind: 'dropped-subject' }] });
  check('8. rejects still-flagged', verdict.reason === 'still-flagged', JSON.stringify(verdict));
}

// 9. rejects length ratio
{
  const original = 'Mara walked slowly across the wide, echoing room toward the heavy door at the far end.';
  const candidate = 'Mara left.';
  const verdict = verifyRegeneratedParagraph(original, candidate, { cast: CAST });
  check('9. rejects length ratio', verdict.reason === 'length-ratio', JSON.stringify(verdict));
}

// 10. rejects worse quote balance
{
  const original = '“Mara said the door was open,” Dov replied evenly.';
  const candidate = '“Mara said the door was still open, Dov replied evenly.';
  const verdict = verifyRegeneratedParagraph(original, candidate, { cast: CAST });
  check('10. rejects worse quote balance', verdict.reason === 'quote-balance', JSON.stringify(verdict));
}

// 11. rejects a 12+-word sentence duplicated from priorProse
{
  const original = 'Mara sat by the fire and stared into the flames for a long while, unable to sleep.';
  const candidate = 'She thought of the quiet of the desert, the way the stars looked from the mesa that night.';
  const priorProse = ['She thought of the quiet of the desert, the way the stars looked from the mesa that night.'];
  const verdict = verifyRegeneratedParagraph(original, candidate, { cast: CAST, priorProse });
  check('11. rejects a 12+-word sentence duplicated from priorProse', verdict.reason === 'prior-duplicate', JSON.stringify(verdict));
}

// 12. rejects a departed name reintroduced
{
  const original = 'Dov sat quietly by the window, watching the storm outside.';
  const candidate = 'Mara walked in and sat quietly by the window, watching the storm outside.';
  const verdict = verifyRegeneratedParagraph(original, candidate, { cast: CAST, departed: ['Mara'] });
  check('12. rejects a departed name reintroduced', verdict.reason === 'departed-reintroduced', JSON.stringify(verdict));
}

// 13. rejects identical candidate
{
  const original = 'Mara walked slowly across the room toward the door.';
  const verdict = verifyRegeneratedParagraph(original, original, { cast: CAST });
  check('13. rejects identical candidate', verdict.reason === 'unchanged', JSON.stringify(verdict));
}

// ── 14. sequential — never more than one LLM call in flight ──
{
  const text = 'Mara walked into the room and sat down.\n\nWere a ragtag collection of misfits, but they kept moving toward the ridge anyway.\n\nDov leaned against the frame and exhaled slowly, watching the door.\n\nWas wearing a heavy coat that dragged along the floor as they moved through the hall.';
  let inFlight = 0; let maxInFlight = 0;
  const mockLLM = async (prompt) => {
    inFlight += 1; maxInFlight = Math.max(maxInFlight, inFlight);
    await new Promise((r) => setTimeout(r, 5));
    inFlight -= 1;
    if (prompt.includes('ragtag')) return 'The group was a ragtag collection of misfits, but they kept moving toward the ridge anyway.';
    return 'The stranger wore a heavy coat that dragged along the floor as they moved through the hall.';
  };
  const result = await regenerateFlaggedParagraphs(text, { cast: CAST, callLLM: mockLLM, project: { book_type: 'fiction' } });
  check('14. sequential — never more than one LLM call in flight', maxInFlight === 1, `maxInFlight=${maxInFlight} regenerated=${result.regenerated}`);
}

// ── 15. maxUnits respected ──
{
  const text = [
    'Were a ragtag collection of misfits, but they kept moving toward the ridge anyway.',
    'Was wearing a heavy coat that dragged along the floor as they moved through the hall.',
    'Had turned away before anyone else could see the look on their face.',
    'Felt the cold settle into their bones as the wind picked up outside.',
  ].join('\n\n');
  const targets = collectRegenTargets(text, { cast: CAST, maxUnits: 2 });
  check('15. maxUnits respected', targets.length === 2, `targets.length=${targets.length}`);
}

// ── 16. mock throws → text unchanged, reason llm-error: ──
{
  const text = 'Mara walked into the room and sat down.\n\nWere a ragtag collection of misfits, but they kept moving toward the ridge anyway.';
  const mockLLM = async () => { throw new Error('model unreachable'); };
  const result = await regenerateFlaggedParagraphs(text, { cast: CAST, callLLM: mockLLM, project: { book_type: 'fiction' } });
  check('16. mock throws → text unchanged, reason llm-error:', result.regenerated === 0 && result.text === text && result.skipped[0]?.reason?.startsWith('llm-error:'), JSON.stringify(result));
}

// ── 17. whole-lane revert when a mocked replacement changes paragraph count ──
{
  const text = 'Mara walked into the room and sat down.\n\nWere a ragtag collection of misfits, but they kept moving toward the ridge anyway.';
  const mockLLM = async () => 'The group was a ragtag collection of misfits, but they kept moving toward the ridge anyway.';
  const result = await regenerateFlaggedParagraphs(text, { cast: CAST, callLLM: mockLLM, project: { book_type: 'fiction' }, _forceParagraphMismatchForTest: true });
  check('17. whole-lane revert when paragraph count changes', result.regenerated === 0 && result.text === text && result.skipped.every((s) => s.reason === 'lane-reverted'), JSON.stringify(result));
}

// ── 18. NF project → nf-skip, text unchanged ──
{
  const text = 'Were a ragtag collection of misfits, but they kept moving toward the ridge anyway.';
  const mockLLM = async () => 'should never be called';
  const result = await regenerateFlaggedParagraphs(text, { cast: CAST, callLLM: mockLLM, project: { book_type: 'nonfiction' } });
  check('18. NF project → nf-skip, text unchanged', result.regenerated === 0 && result.text === text && result.skipped[0]?.reason === 'nf-skip', JSON.stringify(result));
}

// ── 19-20. source-shape wiring ──
{
  const SW = fs.readFileSync(new URL('../src/lib/sceneWriter.js', import.meta.url), 'utf8');
  const finalizeStart = SW.indexOf('export async function finalizeChapterProse');
  const finalizeEnd = SW.indexOf('\nexport ', finalizeStart + 50);
  const finalizeBody = finalizeStart >= 0 ? SW.slice(finalizeStart, finalizeEnd > finalizeStart ? finalizeEnd : finalizeStart + 20000) : '';
  check('19. sceneWriter.js finalizeChapterProse wires the regen lane', finalizeBody.includes('regenerateFlaggedParagraphs') && finalizeBody.includes('[REGENLANE]'));

  const RUNNER = fs.readFileSync(new URL('../src/lib/manuscriptPolishRunner.js', import.meta.url), 'utf8');
  check("20. manuscriptPolishRunner.js has verifyInvariant('Regenerate Lane')", RUNNER.includes("verifyInvariant('Regenerate Lane')") && RUNNER.includes('regenerateFlaggedParagraphs'));
}

console.log(failures === 0 ? '\nACCEPTANCE: ALL CHECKS MATCHED' : `\nACCEPTANCE: ${failures} CHECK(S) DID NOT MATCH`);
process.exit(failures === 0 ? 0 : 1);
